import { t } from '@/i18n/index.js';

/**
 * The one-tap requests a learner can send back with a card. The label is
 * what they see; the hint is the English sentence the model receives, kept
 * in one place so every screen asks for the same thing.
 */
export const REFINEMENTS = [
  {
    key: 'simpler',
    labelKey: 'ai.refineSimpler',
    hint: 'simpler: shorter meanings and easier example sentences, for a beginner',
  },
  {
    key: 'examples',
    labelKey: 'ai.refineExamples',
    hint: 'more example sentences, from everyday situations',
  },
  {
    key: 'formal',
    labelKey: 'ai.refineFormal',
    hint: 'formal register: how the word is used in writing and at work',
  },
] as const;

export type RefinementKey = (typeof REFINEMENTS)[number]['key'];

/** The label for a refinement, translated. */
export function refinementLabel(key: RefinementKey): string {
  const found = REFINEMENTS.find((item) => item.key === key);
  return found === undefined ? key : t(found.labelKey);
}

/** The longest hint the server accepts; the contract enforces the same number. */
export const MAX_HINT_LENGTH = 200;
